import re

HEAD = re.compile(r"^(?P<index>\d+): (?P<interface>[^:]+): <(?P<flags>[^>]*)>(?P<attrs>.*)$")
ADDR = re.compile(r"^\s+(?P<family>inet6?) (?P<address>\S+)(?P<attrs>.*)$")
LINK = re.compile(r"^\s+link/(?P<type>\S+) (?P<mac>\S+)(?: brd (?P<brd>\S+))?")
LFT = re.compile(r"^\s+valid_lft (?P<valid_lft>\S+) preferred_lft (?P<preferred_lft>\S+)$")


def pairs(text):
    # "mtu 1500 qdisc fq_codel state UP" -> {"mtu": "1500", ...}; lone words
    # (dynamic, noprefixroute) are flags
    out, toks = {}, text.split()
    i = 0
    while i < len(toks):
        if toks[i] in ("mtu", "qdisc", "state", "group", "qlen", "brd", "scope"):
            if i + 1 < len(toks):
                out[toks[i]] = toks[i + 1]
            i += 2
        else:
            out.setdefault("flags", [])
            out["flags"].append(toks[i])
            i += 1
    if "flags" in out:
        out["flags"] = ",".join(out["flags"])
    return out


def parse(lines):
    ifaces, addrs, used_i, used_a = [], [], [], []
    iface = None
    for j, ln in enumerate(lines):
        m = HEAD.match(ln)
        if m:
            iface = {"index": m.group("index"), "interface": m.group("interface"),
                     "flags": m.group("flags")}
            iface.update(pairs(m.group("attrs")))
            ifaces.append(iface)
            used_i.append(j)
            continue
        if iface is None:
            continue
        m = LINK.match(ln)
        if m:
            iface["link_type"] = m.group("type")
            iface["mac"] = m.group("mac")
            used_i.append(j)
            continue
        m = ADDR.match(ln)
        if m:
            addr = {"interface": iface["interface"], "family": m.group("family"),
                    "address": m.group("address")}
            a = pairs(m.group("attrs"))
            for k in ("brd", "scope", "flags"):
                if k in a:
                    addr[k] = a[k]
            # the scope's own name (lo, enp3s0) rides in flags: drop it
            if addr.get("flags"):
                addr["flags"] = ",".join(f for f in addr["flags"].split(",") if f != iface["interface"])
                if not addr["flags"]:
                    del addr["flags"]
            addrs.append(addr)
            used_a.append(j)
            continue
        m = LFT.match(ln)
        if m and addrs:
            addrs[-1]["valid_lft"] = m.group("valid_lft")
            addrs[-1]["preferred_lft"] = m.group("preferred_lft")
            used_a.append(j)
    return [{"name": "interfaces", "kind": "table", "lines": used_i, "records": ifaces},
            {"name": "addresses", "kind": "table", "lines": used_a, "records": addrs}]
